Q: How can I make my tangent numbers generating class resumable? A: <p>Here is some C++ code to calculate A000182 using 'memoization'</p>
<pre class="lang-cpp prettyprint-override"><code>#include &lt;string&gt;
#include &lt;sstream&gt;
#include &lt;iostream&gt;
#include &lt;vector&gt;

#include &quot;cRunWatch.h&quot;

long long factorial(int n)
{
    // memoization strore
    static std::vector&lt;long long&gt; vfacts;
    if (!vfacts.size())
    {
        //fill first values
        vfacts.push_back(0);
        vfacts.push_back(1);
    }

    if (n &lt; vfacts.size())
        return vfacts[n];

    for (int k = vfacts.size(); k &lt;= n; k++)
    {
        vfacts.push_back(vfacts.back() * k);
    }
    return vfacts.back();
}

int combCount(int N, int K)
{
    if (K &gt; N)
        throw std::runtime_error(
            &quot;combcount&quot;);
    return factorial(N) / (factorial(K) * factorial(N - K));
}

long long A000182(int n)
{
    // memoization store for first 50 values
    static std::vector&lt;long long&gt; memo(50,-1);

    if( n &gt; 50 )
        throw std::runtime_error(
            &quot;Number too high&quot;        );

    if (!memo.size())
    {
        // fill first values
        memo[0] = 0;
        memo[1] = 1;
    }

    if (n == 1)
        return 1;

    if (memo[n] &gt; 0 )
        return memo[n];

    long long s = 0;
    for (int k = 1; k &lt; n; k++)
        s += combCount(2 * n - 2, 2 * k - 1) * A000182(k) * A000182(n - k);

    memo[n] = s;
    return s;
}

main()
{
    raven::set::cRunWatch::Start();
    long long r10_1,r10_2;
    {
        raven::set::cRunWatch aWatcher(&quot;calculate #10&quot;);
        r10_1 = A000182(10);
    }
    {
        raven::set::cRunWatch aWatcher(&quot;calculate #10 again&quot;);
        r10_2 = A000182(10);
    }
    std::cout &lt;&lt; r10_1 &lt;&lt;&quot; &quot;&lt;&lt; r10_2 &lt;&lt; &quot;\n&quot;;


    raven::set::cRunWatch::Report();


    return 0;
}

</code></pre>
